// features/auth.feature: Signing out clears the session cookie
import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in so the request context holds a session cookie
  await expectStatus(await request.post("/api/auth/login", { data: { email: USERS.member, password: PASSWORD } }), 200);
  const before = await request.storageState();
  expect(before.cookies.map((c) => c.name)).toContain("session");

  // Act
  const response = await request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie" && /^session=/.test(h.value));
  expect(cookie?.value, "logout sets a Set-Cookie header for session").toMatch(/^session=(""|);/);
  expect(cookie?.value.toLowerCase()).toContain("max-age=0");
  const after = await request.storageState();
  expect(after.cookies.map((c) => c.name)).not.toContain("session");
});
